// Build the release request.
//
// Everything is optional except the reason: Arena derives its own defaults and
// re-checks every guard, so this node never decides whether a release is
// allowed — only what is being asked for.
//
// Times are Asia/Jakarta wall clock and are sent as explicit +07:00 instants,
// because the workflow timezone and the Arena server timezone are not the same
// thing and "08:00" alone would be ambiguous between them.
const body = $json.body ?? {};

function wib(dayOffset, hour, minute) {
  const now = new Date(Date.now() + 7 * 3600000);
  const day = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + dayOffset));
  const date = day.toISOString().slice(0, 10);
  return `${date}T${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}:00+07:00`;
}

const opensAt = body.opensAt ?? wib(0, 8, 0);
const submissionDeadlineAt = body.submissionDeadlineAt ?? wib(4, 23, 59);

return [{
  json: {
    opensAt,
    submissionDeadlineAt,
    // Approving skips Arena's minimum preview interval. Left false here on
    // purpose: an unattended workflow should prepare the release and let a
    // human approve, unless the caller explicitly asks otherwise.
    approve: body.approve === true,
    publish: body.publish === true,
    ...(body.weekId ? { weekId: body.weekId } : {}),
    ...(body.weekCode ? { weekCode: body.weekCode } : {}),
    ...(body.title ? { title: body.title } : {}),
    ...(body.divisionId ? { divisionId: body.divisionId } : {}),
    reason: body.reason ?? 'Rilis di luar jadwal via n8n',
  },
}];

// Surface only what a human would act on.
//
// A step reporting `ok: false` is not necessarily a fault: a release prepared
// for Tuesday cannot publish on Monday, and Arena says so rather than forcing
// it. Publication being "not due" is the expected quiet case.
const out = [];
for (const item of $input.all()) {
  const status = item.json.statusCode;
  const data = item.json.body?.data;
  const error = item.json.body?.error;

  if (status !== 200 || !data) {
    out.push({ json: { alert: true, status, code: error?.code ?? 'UNKNOWN', message: error?.message ?? 'Arena rejected the release.' } });
    continue;
  }

  const problems = (data.steps ?? []).filter((step) => !step.ok);
  out.push({
    json: {
      alert: problems.length > 0,
      weekCode: data.weekCode,
      created: data.created,
      steps: (data.steps ?? []).map((step) => `${step.step}:${step.ok ? 'ok' : 'attention'}`).join(' '),
      problems,
    },
  });
}
return out;
